mapper.select:
SELECT CASE WHEN u.token_version = #{tokenVersion}
AND EXISTS (SELECT 1 FROM refresh_tokens r WHERE r.session_id = #{sessionId} AND r.user_id = u.user_id AND r.revoked_at IS NULL AND r.expires_at > CURRENT_TIMESTAMP)
THEN 1 ELSE 0 END FROM users u WHERE u.user_id = #{userId} AND u.status = 'ACTIVE'
